import { apiBase, supabaseConfigured } from './lib/supabase';
const S = { view: 'home', role: 'client', dark: false, lang: 'en', mood: 7 };
const logo = '/assets/assets/brand/logo-mark.svg', hero = '/assets/assets/illustrations/therapy-hero.svg', moodArt = '/assets/assets/illustrations/mood-card.svg';
const txt = { en: { start: 'Start your healing journey', signIn: 'Sign in', subtitle: 'Personalized therapy support for families, clients, and clinicians—grounded in CBT, compassionate AI, and secure care coordination.' }, es: { start: 'Comienza tu camino de bienestar', signIn: 'Iniciar sesión', subtitle: 'Apoyo terapéutico personalizado para familias, clientes y terapeutas con CBT, IA compasiva y coordinación segura.' } };
const root = document.getElementById('root');
const icon = (x) => `<span class="ico">${x}</span>`;
const set = (patch) => { Object.assign(S, patch); render(); };
function render() { const t = txt[S.lang]; root.innerHTML = `<main class="app ${S.dark ? 'dark' : ''}"><aside class="rail"><button class="brand" data-view="home"><img src="${logo}"><span>Therafam</span></button>${nav()}<div class="railBottom"><button data-lang>${icon('🌐')}<span>${S.lang.toUpperCase()}</span></button><button data-theme>${icon(S.dark ? '☀️' : '🌙')}<span>Theme</span></button></div></aside><section class="canvas"><header><div><p class="eyebrow">Secure mental health platform</p><h1>${t.start}</h1></div><button class="pill" data-view="auth">${t.signIn} ›</button></header>${screen()}</section></main>`; bind(); }
function nav() { return [['home', '🏠', 'Home'], ['client', '🤝', 'Client'], ['therapist', '👥', 'Therapist'], ['ai', '🧠', 'AI Chat'], ['programs', '▶️', 'Programs'], ['messages', '💬', 'Messages'], ['settings', '⚙️', 'Settings']].map(([id, i, l]) => `<button class="${S.view === id ? 'active' : ''}" data-view="${id}">${icon(i)}<span>${l}</span></button>`).join(''); }
function screen() {
    const t = txt[S.lang];
    if (S.view === 'home')
        return `<section class="hero"><div><div class="badge">${icon('🌿')} CBT + family systems + AI support</div><h2>Care that feels warm, intelligent, and human.</h2><p>${t.subtitle}</p><div class="actions"><button data-view="auth">Create account</button><button class="ghost" data-view="ai">Try AI companion</button></div></div><img src="${hero}"></section><section class="grid three">${['Mood tracking|Daily check-ins, trends, and personalized coping recommendations.', 'Therapist matching|Verified providers, secure appointments, and collaborative care plans.', 'Guided programs|CBT lessons, breathwork, journaling, and family communication skills.'].map(card).join('')}</section>`;
    if (S.view === 'auth')
        return `<section class="auth"><div class="panel"><h2>Welcome back</h2><p>Sign in securely as a client or therapist. Supabase is used when configured; secrets remain on the server.</p><div class="seg"><button class="${S.role === 'client' ? 'sel' : ''}" data-role="client">Client</button><button class="${S.role === 'therapist' ? 'sel' : ''}" data-role="therapist">Therapist</button></div><input placeholder="Email address"><input placeholder="Password" type="password"><button data-view="${S.role}">${supabaseConfigured ? 'Continue with Supabase' : 'Continue demo'}</button><small>${apiBase ? `API: ${apiBase}` : 'Connect VITE_API_BASE_URL for backend AI chat.'}</small></div><div class="panel soft">${icon('🛡️')}<h3>Private by design</h3><p>Email verification, therapist profile review, protected session notes, and crisis escalation UI are ready for production integration.</p></div></section>`;
    if (S.view === 'client')
        return `<section class="dash"><div class="welcome"><h2>Good afternoon, Maya</h2><p>Your plan today focuses on anxiety relief, family boundaries, and sleep hygiene.</p></div><div class="grid two"><article class="card mood"><img src="${moodArt}"><h3>How are you feeling?</h3><input data-mood type="range" min="1" max="10" value="${S.mood}"><b>${S.mood}/10 — steady and hopeful</b></article><article class="card"><h3>Next appointment</h3><p class="big">Today · 4:30 PM</p><p>Video session with Dr. Rivera</p><button>Join waiting room</button></article></div></section>`;
    if (S.view === 'therapist')
        return `<section class="dash"><h2>Therapist workspace</h2><div class="grid three">${['8 clients active', '4 sessions today', '3 notes pending'].map(x => `<article class="stat">${x}</article>`).join('')}</div><article class="card"><h3>Client risk board</h3>${['Maya — improving mood trend', 'Jon — missed check-in', 'Family A — new message'].map(row).join('')}</article></section>`;
    if (S.view === 'ai')
        return chat('Therafam AI companion', ['I can help you reframe thoughts, practice grounding, and decide when to contact your therapist.|ai', 'I feel overwhelmed after an argument.|me', 'Let’s slow down. Name one body sensation, one thought, and one need you can express calmly.|ai'], 'Message Therafam AI...');
    if (S.view === 'programs')
        return `<section><h2>Programs & lessons</h2><div class="grid three">${['CBT foundations', 'Family communication', 'Sleep reset', 'Mindful parenting', 'Anxiety toolkit', 'Crisis safety plan'].map(x => `<article class="card program">${icon('▶️')}<h3>${x}</h3><p>Short lesson · guided practice · progress saved</p></article>`).join('')}</div></section>`;
    if (S.view === 'messages')
        return chat('Secure messages', ['Dr. Rivera: Please complete the reflection before our session.|ai', 'Maya: I updated my mood log.|me', 'System: Appointment reminder sent.|ai'], 'Write a secure message...');
    return `<section><h2>Settings</h2><article class="card"><p class="row">Language <button data-lang>${S.lang === 'en' ? 'English' : 'Español'}</button></p><p class="row">Theme <button data-theme>${S.dark ? 'Dark' : 'Light'}</button></p><p class="row">Notifications <button>Enabled</button></p></article></section>`;
}
function card(s) { const [h, p] = s.split('|'); return `<article class="card">${icon('✨')}<h3>${h}</h3><p>${p}</p></article>`; }
function row(x) { return `<p class="row">${x}<span>›</span></p>`; }
function chat(h, items, ph) { return `<section class="chat"><h2>${h}</h2>${items.map(i => { const [m, c] = i.split('|'); return `<div class="bubble ${c}">${m}</div>`; }).join('')}<div class="composer"><input placeholder="${ph}"><button>Send</button></div></section>`; }
function bind() { document.querySelectorAll('[data-view]').forEach(b => b.onclick = () => set({ view: b.dataset.view })); document.querySelectorAll('[data-role]').forEach(b => b.onclick = () => set({ role: b.dataset.role })); document.querySelectorAll('[data-theme]').forEach(b => b.onclick = () => set({ dark: !S.dark })); document.querySelectorAll('[data-lang]').forEach(b => b.onclick = () => set({ lang: S.lang === 'en' ? 'es' : 'en' })); document.querySelectorAll('[data-mood]').forEach(i => i.oninput = () => set({ mood: Number(i.value) })); }
render();
